import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        char[] s = new String(System.in.readAllBytes()).trim().toCharArray();
        // Parity of each position is fixed; each parity class can be fully rearranged.
        char[] odd = new char[s.length], even = new char[s.length];
        int no = 0, ne = 0;
        for (char c : s) {
            if ((c - '0') % 2 == 1) odd[no++] = c;
            else even[ne++] = c;
        }
        Arrays.sort(odd, 0, no);
        Arrays.sort(even, 0, ne);
        // Sorted ascending, so take from the back for descending order.
        for (int k = 0; k < s.length; k++) s[k] = (s[k] - '0') % 2 == 1 ? odd[--no] : even[--ne];
        System.out.print(new String(s) + "\n");
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

func main() {
	var str string
	fmt.Fscan(bufio.NewReader(os.Stdin), &str)
	s := []byte(str)
	// Parity of each position is fixed; each parity class can be fully rearranged.
	var odd, even []byte
	for _, c := range s {
		if (c-'0')%2 == 1 {
			odd = append(odd, c)
		} else {
			even = append(even, c)
		}
	}
	desc := func(b []byte) { sort.Slice(b, func(i, j int) bool { return b[i] > b[j] }) }
	desc(odd)
	desc(even)
	i, j := 0, 0
	for k, c := range s {
		if (c-'0')%2 == 1 {
			s[k] = odd[i]
			i++
		} else {
			s[k] = even[j]
			j++
		}
	}
	fmt.Println(string(s))
}
